SELECT id, receiver_tenant_id, type, title, content, related_type, related_id, from_tenant_id, from_user_id, is_read, read_time, create_time, update_time, is_deleted FROM notification WHERE receiver_tenant_id = #{tenantId} AND is_deleted = 0
AND is_read = 0
ORDER BY is_read ASC, create_time DESC LIMIT #{offset}, #{limit}
